CREATE TABLE public.lab_lessons (
  slug text PRIMARY KEY,
  sort integer NOT NULL,
  band text NOT NULL,
  title jsonb NOT NULL,
  body jsonb NOT NULL,
  example text NOT NULL DEFAULT '',
  challenge_ids text[] NOT NULL DEFAULT '{}'
);
GRANT SELECT ON public.lab_lessons TO anon, authenticated;
GRANT ALL ON public.lab_lessons TO service_role;
ALTER TABLE public.lab_lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Lessons are readable" ON public.lab_lessons FOR SELECT USING (true);

CREATE TABLE public.challenge_solutions (
  challenge_id text PRIMARY KEY REFERENCES public.coding_challenges(id) ON DELETE CASCADE,
  code jsonb NOT NULL,
  explanation jsonb NOT NULL
);
GRANT ALL ON public.challenge_solutions TO service_role;
ALTER TABLE public.challenge_solutions ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.get_solution(_challenge_id text, _language text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('code', s.code->>_language, 'explanation', s.explanation)
  FROM public.challenge_solutions s
  WHERE s.challenge_id = _challenge_id
    AND EXISTS (SELECT 1 FROM public.challenge_completions c
                WHERE c.user_id = auth.uid() AND c.challenge_id = _challenge_id AND c.language = _language)
$$;
REVOKE ALL ON FUNCTION public.get_solution(text, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.get_solution(text, text) TO authenticated;

INSERT INTO public.lab_lessons (slug, sort, band, title, body, example, challenge_ids) VALUES
('intro',1,'beginner','{"en":"Introduction to Python","ar":"مقدمة إلى Python","fr":"Introduction à Python"}',
 '{"en":"Python runs your code line by line from top to bottom. print() shows a value in the console. Lines starting with # are comments and are ignored.","ar":"تنفّذ Python الكود سطراً بسطر من الأعلى إلى الأسفل. الدالة print() تعرض قيمة في الـ Console. الأسطر التي تبدأ بـ # تعليقات يتم تجاهلها.","fr":"Python exécute le code ligne par ligne, de haut en bas. print() affiche une valeur dans la console. Les lignes commençant par # sont des commentaires."}',
 E'# My first program\nprint("Hello, DevHub!")\nprint(2 + 3)', '{lab_greet}'),
('variables',2,'beginner','{"en":"Variables","ar":"المتغيرات","fr":"Les variables"}',
 '{"en":"A variable is a name that stores a value: age = 20. You can reuse and change it later. Names are case-sensitive and cannot start with a digit.","ar":"المتغير اسم يخزّن قيمة: age = 20. يمكنك إعادة استعماله وتغييره لاحقاً. الأسماء حساسة لحالة الأحرف ولا تبدأ برقم.","fr":"Une variable est un nom qui stocke une valeur : age = 20. On peut la réutiliser et la modifier. Les noms sont sensibles à la casse et ne commencent pas par un chiffre."}',
 E'name = "Sara"\nage = 20\nage = age + 1\nprint(name, age)', '{lab_greet,lab_area}'),
('types',3,'beginner','{"en":"Data Types","ar":"أنواع البيانات","fr":"Types de données"}',
 '{"en":"Main types: int (5), float (2.5), str (\"hi\"), bool (True/False). type(x) tells you the type. int(\"7\") and str(7) convert between types.","ar":"الأنواع الأساسية: int (5)، float (2.5)، str (\"hi\")، bool (True/False). type(x) يعرض النوع، وint(\"7\") وstr(7) للتحويل بين الأنواع.","fr":"Types principaux : int (5), float (2.5), str (\"hi\"), bool (True/False). type(x) donne le type ; int(\"7\") et str(7) convertissent."}',
 E'x = 7\ny = 2.5\ns = "7"\nprint(type(x), type(y), type(s))\nprint(x + int(s))', '{lab_area}'),
('io',4,'beginner','{"en":"Input and Output","ar":"الإدخال والإخراج","fr":"Entrées et sorties"}',
 '{"en":"input() reads a line typed by the user and always returns text. Convert it with int() or float() for numbers. f-strings format output: f\"Hi {name}\". Type your inputs in the Input box before pressing Run.","ar":"input() تقرأ سطراً يكتبه المستخدم وتعيد دائماً نصاً. حوّله بـ int() أو float() للأرقام. وتُستعمل f-strings لتنسيق الإخراج: f\"Hi {name}\". اكتب مدخلاتك في خانة الإدخال قبل الضغط على تشغيل.","fr":"input() lit une ligne saisie et renvoie toujours du texte. Convertissez avec int() ou float(). Les f-strings formatent : f\"Salut {name}\". Saisissez vos entrées dans la zone Entrée avant Run."}',
 E'name = input("Your name: ")\nage = int(input("Your age: "))\nprint(f"Hi {name}, next year you will be {age + 1}")', '{lab_time}'),
('operators',5,'beginner','{"en":"Operators","ar":"العمليات","fr":"Les opérateurs"}',
 '{"en":"Arithmetic: + - * / // % **. // is integer division, % is the remainder. Comparison: == != < > <= >=. Logic: and, or, not.","ar":"الحسابية: + - * / // % **. العلامة // للقسمة الصحيحة و% لباقي القسمة. المقارنة: == != < > <= >=. المنطقية: and وor وnot.","fr":"Arithmétique : + - * / // % **. // est la division entière, % le reste. Comparaison : == != < > <= >=. Logique : and, or, not."}',
 E'print(17 // 5, 17 % 5, 2 ** 3)\nprint(5 > 3 and 2 == 2)', '{lab_time,lab_even}'),
('conditions',6,'easy','{"en":"If / Elif / Else","ar":"If / Elif / Else","fr":"If / Elif / Else"}',
 '{"en":"if runs a block only when a condition is True. elif checks another condition, else catches everything left. Indentation (4 spaces) marks the block.","ar":"تنفّذ if الكتلة فقط إذا كان الشرط صحيحاً. تفحص elif شرطاً آخر، وتلتقط else كل ما تبقى. الإزاحة (4 مسافات) تحدد الكتلة.","fr":"if exécute un bloc seulement si la condition est vraie. elif teste une autre condition, else attrape le reste. L’indentation (4 espaces) délimite le bloc."}',
 E'n = int(input("Number: "))\nif n > 0:\n    print("positive")\nelif n == 0:\n    print("zero")\nelse:\n    print("negative")', '{lab_even,lab_grade,lab_leap}'),
('loops',7,'easy','{"en":"For and While Loops","ar":"حلقات For وWhile","fr":"Boucles for et while"}',
 '{"en":"for repeats over a sequence: for i in range(5). while repeats as long as a condition is True — make sure it eventually becomes False. break exits a loop early.","ar":"تكرر for على تسلسل: for i in range(5). وتكرر while ما دام الشرط صحيحاً؛ تأكد أنه يصبح خاطئاً في النهاية. تخرج break من الحلقة مبكراً.","fr":"for parcourt une séquence : for i in range(5). while répète tant que la condition est vraie — elle doit finir par devenir fausse. break sort de la boucle."}',
 E'for i in range(1, 4):\n    print("for", i)\nn = 3\nwhile n > 0:\n    print("while", n)\n    n -= 1', '{lab_sumto,lab_digits,lab_firstmul}'),
('lists',8,'intermediate','{"en":"Lists and Tuples","ar":"القوائم والصفوف","fr":"Listes et tuples"}',
 '{"en":"A list holds ordered values: nums = [3, 1, 2]. Index from 0, append() adds, len() counts, slicing nums[1:3] cuts. A tuple (1, 2) is like a list that cannot change.","ar":"تحفظ القائمة قيماً مرتبة: nums = [3, 1, 2]. الفهرسة تبدأ من 0، وappend() تضيف، وlen() تعدّ، والتقطيع nums[1:3] يقتطع. الصف (1, 2) مثل قائمة لا يمكن تعديلها.","fr":"Une liste contient des valeurs ordonnées : nums = [3, 1, 2]. Index à partir de 0, append() ajoute, len() compte, nums[1:3] découpe. Un tuple (1, 2) est une liste non modifiable."}',
 E'nums = [3, 1, 2]\nnums.append(5)\nprint(nums[0], len(nums), nums[1:3])\npoint = (2, 4)\nprint(point[1])', '{lab_vowels,lab_revwords,lab_max}'),
('functions',9,'intermediate','{"en":"Functions","ar":"الدوال","fr":"Les fonctions"}',
 '{"en":"def creates a reusable function. Parameters receive values; return sends a result back. A function without return gives None.","ar":"تنشئ def دالة قابلة لإعادة الاستعمال. تستقبل المعاملات القيم، وتعيد return نتيجة. الدالة بدون return تعيد None.","fr":"def crée une fonction réutilisable. Les paramètres reçoivent des valeurs ; return renvoie un résultat. Sans return, la fonction renvoie None."}',
 E'def add(a, b):\n    return a + b\n\nprint(add(2, 3))', '{lab_square,lab_discount,lab_power}'),
('dicts',10,'intermediate','{"en":"Dictionaries","ar":"القواميس","fr":"Les dictionnaires"}',
 '{"en":"A dictionary maps keys to values: ages = {\"Ali\": 20}. Read with ages[\"Ali\"], add with ages[\"Sara\"] = 22, and use .get(key, default) to avoid errors.","ar":"يربط القاموس مفاتيح بقيم: ages = {\"Ali\": 20}. اقرأ بـ ages[\"Ali\"] وأضف بـ ages[\"Sara\"] = 22، واستعمل .get(key, default) لتجنب الأخطاء.","fr":"Un dictionnaire associe des clés à des valeurs : ages = {\"Ali\": 20}. Lire avec ages[\"Ali\"], ajouter avec ages[\"Sara\"] = 22, .get(clé, défaut) évite les erreurs."}',
 E'counts = {}\nfor w in "a b a".split():\n    counts[w] = counts.get(w, 0) + 1\nprint(counts)', '{lab_freq,lab_twosum}'),
('algorithms',11,'advanced','{"en":"Basic Algorithms","ar":"الخوارزميات الأساسية","fr":"Algorithmes de base"}',
 '{"en":"An algorithm is a precise step-by-step recipe. Common patterns: scan a list keeping the best value, compare from both ends, store seen values in a dictionary, or let a function call itself (recursion).","ar":"الخوارزمية وصفة دقيقة خطوة بخطوة. أنماط شائعة: المرور على قائمة مع حفظ أفضل قيمة، المقارنة من الطرفين، حفظ القيم المرئية في قاموس، أو دالة تستدعي نفسها (العودية).","fr":"Un algorithme est une recette précise étape par étape. Motifs courants : parcourir en gardant la meilleure valeur, comparer des deux extrémités, mémoriser dans un dictionnaire, ou la récursion."}',
 E'def countdown(n):\n    if n == 0:\n        return [0]\n    return [n] + countdown(n - 1)\n\nprint(countdown(3))', '{lab_palin,lab_fizz,lab_flatten,lab_roman}');

INSERT INTO public.challenge_solutions (challenge_id, code, explanation) VALUES
('lab_greet', jsonb_build_object('python', E'def greet(name):\n    return f"Hello, {name}!"', 'javascript', E'function greet(name) {\n  return `Hello, ${name}!`;\n}'), '{"en":"Build the text with an f-string / template literal and return it.","ar":"نبني النص باستعمال f-string أو template literal ثم نعيده.","fr":"On construit le texte avec une f-string / template literal et on le renvoie."}'),
('lab_area', jsonb_build_object('python', E'def rectangle_area(w, h):\n    return w * h', 'javascript', E'function rectangle_area(w, h) {\n  return w * h;\n}'), '{"en":"Area is width multiplied by height.","ar":"المساحة هي العرض مضروباً في الطول.","fr":"L’aire est la largeur multipliée par la hauteur."}'),
('lab_time', jsonb_build_object('python', E'def seconds_to_minutes(s):\n    return [s // 60, s % 60]', 'javascript', E'function seconds_to_minutes(s) {\n  return [Math.floor(s / 60), s % 60];\n}'), '{"en":"Integer division gives full minutes; the remainder gives leftover seconds.","ar":"القسمة الصحيحة تعطي الدقائق الكاملة، والباقي يعطي الثواني المتبقية.","fr":"La division entière donne les minutes ; le reste donne les secondes."}'),
('lab_even', jsonb_build_object('python', E'def is_even(n):\n    return n % 2 == 0', 'javascript', E'function is_even(n) {\n  return n % 2 === 0;\n}'), '{"en":"A number is even when dividing by 2 leaves no remainder.","ar":"يكون العدد زوجياً إذا لم يبقَ باقٍ عند قسمته على 2.","fr":"Un nombre est pair si le reste de la division par 2 est nul."}'),
('lab_grade', jsonb_build_object('python', E'def grade(score):\n    if score >= 90:\n        return "A"\n    elif score >= 80:\n        return "B"\n    elif score >= 70:\n        return "C"\n    elif score >= 60:\n        return "D"\n    return "F"', 'javascript', E'function grade(score) {\n  if (score >= 90) return "A";\n  if (score >= 80) return "B";\n  if (score >= 70) return "C";\n  if (score >= 60) return "D";\n  return "F";\n}'), '{"en":"Check thresholds from highest to lowest so the first match wins.","ar":"نفحص الحدود من الأعلى إلى الأدنى فيفوز أول شرط صحيح.","fr":"On teste les seuils du plus haut au plus bas ; le premier qui correspond gagne."}'),
('lab_leap', jsonb_build_object('python', E'def is_leap_year(y):\n    return (y % 4 == 0 and y % 100 != 0) or y % 400 == 0', 'javascript', E'function is_leap_year(y) {\n  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;\n}'), '{"en":"Divisible by 4 but not 100, unless divisible by 400.","ar":"يقبل القسمة على 4 وليس على 100، إلا إذا قبل القسمة على 400.","fr":"Divisible par 4 mais pas par 100, sauf si divisible par 400."}'),
('lab_sumto', jsonb_build_object('python', E'def sum_to(n):\n    total = 0\n    for i in range(1, n + 1):\n        total += i\n    return total', 'javascript', E'function sum_to(n) {\n  let total = 0;\n  for (let i = 1; i <= n; i++) total += i;\n  return total;\n}'), '{"en":"Keep a running total and add every number from 1 to n.","ar":"نحتفظ بمجموع تراكمي ونضيف كل عدد من 1 إلى n.","fr":"On garde un total cumulé en ajoutant chaque nombre de 1 à n."}'),
('lab_digits', jsonb_build_object('python', E'def count_digits(n):\n    n = abs(n)\n    count = 1\n    while n >= 10:\n        n //= 10\n        count += 1\n    return count', 'javascript', E'function count_digits(n) {\n  n = Math.abs(n);\n  let count = 1;\n  while (n >= 10) { n = Math.floor(n / 10); count++; }\n  return count;\n}'), '{"en":"Remove the last digit with // 10 until one digit is left, counting each step.","ar":"نحذف آخر رقم بـ // 10 حتى يبقى رقم واحد، مع عدّ كل خطوة.","fr":"On retire le dernier chiffre avec // 10 jusqu’à un seul chiffre, en comptant."}'),
('lab_firstmul', jsonb_build_object('python', E'def first_multiple(nums, k):\n    for x in nums:\n        if x % k == 0:\n            return x\n    return None', 'javascript', E'function first_multiple(nums, k) {\n  for (const x of nums) if (x % k === 0) return x;\n  return null;\n}'), '{"en":"Return as soon as a multiple is found; if the loop ends, there is none.","ar":"نعيد القيمة فور إيجاد مضاعف؛ وإذا انتهت الحلقة فلا يوجد.","fr":"On renvoie dès qu’un multiple est trouvé ; sinon il n’y en a pas."}'),
('lab_square', jsonb_build_object('python', E'def square(n):\n    return n * n', 'javascript', E'function square(n) {\n  return n * n;\n}'), '{"en":"Multiply the number by itself and return it.","ar":"نضرب العدد في نفسه ونعيده.","fr":"On multiplie le nombre par lui-même."}'),
('lab_discount', jsonb_build_object('python', E'def apply_discount(price, percent):\n    return round(price * (100 - percent) / 100, 2)', 'javascript', E'function apply_discount(price, percent) {\n  return Math.round(price * (100 - percent)) / 100;\n}'), '{"en":"Keep (100 - percent)% of the price and round to 2 decimals.","ar":"نبقي (100 - النسبة)% من السعر ونقرّب إلى منزلتين.","fr":"On garde (100 - pourcentage)% du prix, arrondi à 2 décimales."}'),
('lab_power', jsonb_build_object('python', E'def power(base, exp):\n    result = 1\n    for _ in range(exp):\n        result *= base\n    return result', 'javascript', E'function power(base, exp) {\n  let result = 1;\n  for (let i = 0; i < exp; i++) result *= base;\n  return result;\n}'), '{"en":"Start from 1 and multiply by base exp times.","ar":"نبدأ من 1 ونضرب في الأساس عدد مرات الأس.","fr":"On part de 1 et on multiplie par base exp fois."}'),
('lab_vowels', jsonb_build_object('python', E'def count_vowels(s):\n    return sum(1 for ch in s.lower() if ch in "aeiou")', 'javascript', E'function count_vowels(s) {\n  return [...s.toLowerCase()].filter((c) => "aeiou".includes(c)).length;\n}'), '{"en":"Lowercase the text, then count characters that belong to the vowel set.","ar":"نحوّل النص إلى أحرف صغيرة ثم نعدّ الأحرف التي تنتمي إلى حروف العلة.","fr":"On met le texte en minuscules puis on compte les voyelles."}'),
('lab_revwords', jsonb_build_object('python', E'def reverse_words(s):\n    return " ".join(s.split()[::-1])', 'javascript', E'function reverse_words(s) {\n  return s.split(/\\s+/).filter(Boolean).reverse().join(" ");\n}'), '{"en":"Split into words, reverse the list, and join with single spaces.","ar":"نقسم إلى كلمات، نعكس القائمة، ثم نجمعها بمسافة واحدة.","fr":"On découpe en mots, on inverse la liste, puis on joint avec des espaces."}'),
('lab_freq', jsonb_build_object('python', E'def word_frequency(s):\n    counts = {}\n    for w in s.lower().split():\n        counts[w] = counts.get(w, 0) + 1\n    return counts', 'javascript', E'function word_frequency(s) {\n  const counts = {};\n  for (const w of s.toLowerCase().split(/\\s+/).filter(Boolean)) counts[w] = (counts[w] || 0) + 1;\n  return counts;\n}'), '{"en":"Use a dictionary: each word is a key, and its value counts appearances.","ar":"نستعمل قاموساً: كل كلمة مفتاح، وقيمتها عدد مرات ظهورها.","fr":"Un dictionnaire : chaque mot est une clé, sa valeur compte les occurrences."}'),
('lab_max', jsonb_build_object('python', E'def find_max(nums):\n    best = nums[0]\n    for x in nums:\n        if x > best:\n            best = x\n    return best', 'javascript', E'function find_max(nums) {\n  let best = nums[0];\n  for (const x of nums) if (x > best) best = x;\n  return best;\n}'), '{"en":"Remember the largest value seen so far and update it while scanning.","ar":"نحفظ أكبر قيمة رأيناها حتى الآن ونحدّثها أثناء المرور.","fr":"On mémorise la plus grande valeur vue et on la met à jour."}'),
('lab_palin', jsonb_build_object('python', E'def is_palindrome(s):\n    clean = [c.lower() for c in s if c.isalnum()]\n    return clean == clean[::-1]', 'javascript', E'function is_palindrome(s) {\n  const c = s.toLowerCase().replace(/[^a-z0-9]/g, "");\n  return c === [...c].reverse().join("");\n}'), '{"en":"Keep only letters and digits in lowercase, then compare with its reverse.","ar":"نبقي الحروف والأرقام فقط بأحرف صغيرة، ثم نقارنها بمقلوبها.","fr":"On garde lettres et chiffres en minuscules, puis on compare avec l’inverse."}'),
('lab_twosum', jsonb_build_object('python', E'def two_sum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            return [seen[target - x], i]\n        seen[x] = i\n    return []', 'javascript', E'function two_sum(nums, target) {\n  const seen = {};\n  for (let i = 0; i < nums.length; i++) {\n    if (target - nums[i] in seen) return [seen[target - nums[i]], i];\n    seen[nums[i]] = i;\n  }\n  return [];\n}'), '{"en":"Store each value''s index; for each new value check whether its complement was seen.","ar":"نحفظ فهرس كل قيمة، ولكل قيمة جديدة نفحص هل رأينا مكمّلها.","fr":"On stocke l’index de chaque valeur et on vérifie si le complément a été vu."}'),
('lab_fizz', jsonb_build_object('python', E'def fizzbuzz_list(n):\n    out = []\n    for i in range(1, n + 1):\n        if i % 15 == 0:\n            out.append("FizzBuzz")\n        elif i % 3 == 0:\n            out.append("Fizz")\n        elif i % 5 == 0:\n            out.append("Buzz")\n        else:\n            out.append(str(i))\n    return out', 'javascript', E'function fizzbuzz_list(n) {\n  const out = [];\n  for (let i = 1; i <= n; i++) out.push(i % 15 === 0 ? "FizzBuzz" : i % 3 === 0 ? "Fizz" : i % 5 === 0 ? "Buzz" : String(i));\n  return out;\n}'), '{"en":"Test 15 first, then 3, then 5, otherwise use the number as text.","ar":"نفحص 15 أولاً ثم 3 ثم 5، وإلا نستعمل العدد كنص.","fr":"On teste 15 d’abord, puis 3, puis 5, sinon le nombre en texte."}'),
('lab_flatten', jsonb_build_object('python', E'def flatten(items):\n    out = []\n    for x in items:\n        if isinstance(x, list):\n            out.extend(flatten(x))\n        else:\n            out.append(x)\n    return out', 'javascript', E'function flatten(items) {\n  const out = [];\n  for (const x of items) Array.isArray(x) ? out.push(...flatten(x)) : out.push(x);\n  return out;\n}'), '{"en":"Recursion: flatten each inner list and append plain values directly.","ar":"العودية: نسطّح كل قائمة داخلية ونضيف القيم العادية مباشرة.","fr":"Récursion : on aplatit chaque sous-liste et on ajoute les valeurs simples."}'),
('lab_roman', jsonb_build_object('python', E'def roman_to_int(s):\n    v = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}\n    total = 0\n    for i, ch in enumerate(s):\n        if i + 1 < len(s) and v[ch] < v[s[i + 1]]:\n            total -= v[ch]\n        else:\n            total += v[ch]\n    return total', 'javascript', E'function roman_to_int(s) {\n  const v = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };\n  let total = 0;\n  for (let i = 0; i < s.length; i++) total += v[s[i]] < (v[s[i + 1]] || 0) ? -v[s[i]] : v[s[i]];\n  return total;\n}'), '{"en":"Subtract a symbol when a bigger one follows it, otherwise add it.","ar":"نطرح الرمز إذا تبعه رمز أكبر منه، وإلا نضيفه.","fr":"On soustrait un symbole suivi d’un plus grand, sinon on l’ajoute."}');